CREATE TABLE IF NOT EXISTS roadmap_master (
  id_roadmap INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  category VARCHAR(120) NULL,
  target_type ENUM('kuliah','kerja','wirausaha','umum') NOT NULL DEFAULT 'umum',
  recommended_for VARCHAR(120) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_master_active (is_active),
  KEY idx_roadmap_master_target (target_type),
  KEY idx_roadmap_master_category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roadmap_step (
  id_roadmap_step INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  step_order INT NOT NULL DEFAULT 1,
  estimated_duration VARCHAR(80) NULL,
  output_target VARCHAR(180) NULL,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_master (id_roadmap, step_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS roadmap_step_detail (
  id_roadmap_step_detail INT AUTO_INCREMENT PRIMARY KEY,
  id_roadmap_step INT NOT NULL,
  title VARCHAR(180) NOT NULL,
  description TEXT NULL,
  reference_link TEXT NULL,
  reference_type VARCHAR(80) NULL,
  detail_order INT NOT NULL DEFAULT 1,
  is_active TINYINT NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_roadmap_step_detail_step (id_roadmap_step, detail_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SELECT a.id,
       LEFT(CONCAT('Roadmap ', a.nama), 180),
       CONCAT('Roadmap bertahap untuk membantu siswa mempersiapkan pilihan ', a.tujuan_karir, ' pada bidang ', a.nama, '. Roadmap ini dibuat otomatis dari alternatif SPK luas v9.'),
       a.kategori,
       a.tujuan_karir,
       LEFT(a.nama, 120),
       1
FROM alternatives a
WHERE a.sort_order >= 10000;

SELECT rm.id_roadmap, 'Fondasi Bidang dan Target', CONCAT('Pahami gambaran bidang ', rm.recommended_for, ', kompetensi dasar, dan contoh aktivitas nyata.'), 1, '1-2 minggu', 'Ringkasan bidang dan target belajar', 1
FROM roadmap_master rm
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000
  AND NOT EXISTS (SELECT 1 FROM roadmap_step s WHERE s.id_roadmap = rm.id_roadmap AND s.step_order = 1);
SELECT rm.id_roadmap, 'Latihan Skill dan Mini Project', CONCAT('Bangun latihan kecil yang sesuai dengan bidang ', rm.recommended_for, ' agar kemampuan tidak hanya teori.'), 2, '2-4 minggu', 'Mini project atau bukti latihan', 1
FROM roadmap_master rm
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000
  AND NOT EXISTS (SELECT 1 FROM roadmap_step s WHERE s.id_roadmap = rm.id_roadmap AND s.step_order = 2);
SELECT rm.id_roadmap, 'Portofolio, Validasi, dan Rencana Lanjut', CONCAT('Susun bukti hasil belajar bidang ', rm.recommended_for, ', minta masukan guru, lalu tentukan langkah berikutnya.'), 3, '2-3 minggu', 'Portofolio dan rencana lanjut', 1
FROM roadmap_master rm
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000
  AND NOT EXISTS (SELECT 1 FROM roadmap_step s WHERE s.id_roadmap = rm.id_roadmap AND s.step_order = 3);

SELECT s.id_roadmap_step, 'Catat alasan memilih bidang', CONCAT('Tuliskan alasan memilih ', rm.recommended_for, ', kekuatan diri, dan hal yang masih perlu dipelajari.'), NULL, 'aktivitas', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 1
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 1);
SELECT s.id_roadmap_step, 'Cari contoh nyata', CONCAT('Cari contoh jurusan, pekerjaan, bisnis, proyek, atau tokoh yang relevan dengan ', rm.recommended_for, '.'), NULL, 'riset', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 1
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 2);
SELECT s.id_roadmap_step, 'Kerjakan latihan utama', CONCAT('Buat latihan sederhana yang sesuai dengan ', rm.recommended_for, ' dan simpan hasilnya sebagai bukti belajar.'), NULL, 'praktik', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 2
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 1);
SELECT s.id_roadmap_step, 'Minta evaluasi guru', CONCAT('Minta masukan guru atau mentor tentang hasil latihan ', rm.recommended_for, ' agar arah belajar lebih tepat.'), NULL, 'evaluasi', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 2
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 2);
SELECT s.id_roadmap_step, 'Susun portofolio ringkas', CONCAT('Gabungkan catatan, hasil latihan, dan bukti prestasi yang mendukung bidang ', rm.recommended_for, '.'), NULL, 'portofolio', 1, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 3
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 1);
SELECT s.id_roadmap_step, 'Tentukan langkah 30 hari berikutnya', CONCAT('Pilih 1-2 target lanjutan untuk memperkuat kesiapan menuju ', rm.recommended_for, '.'), NULL, 'rencana', 2, 1
FROM roadmap_step s
JOIN roadmap_master rm ON rm.id_roadmap = s.id_roadmap
JOIN alternatives a ON a.id = rm.id_roadmap
WHERE a.sort_order >= 10000 AND s.step_order = 3
  AND NOT EXISTS (SELECT 1 FROM roadmap_step_detail d WHERE d.id_roadmap_step = s.id_roadmap_step AND d.detail_order = 2);
